Json run(VbaWorker& worker,const Json& snapshot,const std::string& source,bool cancel=false){QEventLoop loop;Json result;bool timedOut=false;worker.completed=[&](const Json& value){result=value;loop.quit();};require(worker.start(snapshot,source,"Forecast",true),"worker starts");if(cancel)worker.stop();QTimer timeout;timeout.setSingleShot(true);QObject::connect(&timeout,&QTimer::timeout,&loop,[&]{timedOut=true;worker.stop();loop.quit();});timeout.start(10000);loop.exec();require(!timedOut,"worker completion deadline");return result;}
