 WorkbookSession clean;WorksheetModel cleanModel(clean);QWidget cleanHost;const auto untouched=clean.snapshot();require(vbaCommand(&cleanHost,clean,cleanModel,"vba.editor"),"open clean editor");auto* cleanDialog=cleanHost.findChild<QDialog*>("vba.editor");require(cleanDialog!=nullptr,"clean editor exists");cleanDialog->close();require(clean.snapshot()==untouched,"closing unedited editor does not author a module");
 WorkbookSession swapped;WorksheetModel swappedModel(swapped);QWidget swappedHost;require(vbaCommand(&swappedHost,swapped,swappedModel,"vba.editor"),"open binding editor");auto* bindingDialog=swappedHost.findChild<QDialog*>("vba.editor");bindingDialog->findChild<QPlainTextEdit*>("vba.source")->setPlainText("Sub Forecast()\nRange(\"A1\").Value = 99\nEnd Sub");bindingDialog->findChild<QCheckBox*>("vba.enabled")->setChecked(true);const auto boundRevision=swapped.snapshot()["revision"];bindingDialog->findChild<QPushButton*>("vba.run")->click();VbaWorker* boundWorker=nullptr;for(auto* object:bindingDialog->findChildren<QObject*>())if(auto* candidate=dynamic_cast<VbaWorker*>(object))boundWorker=candidate;require(boundWorker!=nullptr,"binding worker exists");QEventLoop bindingLoop;bool calculated=false;const auto previous=boundWorker->completed;boundWorker->completed=[&](const Json& value){calculated=value["status"]=="completed";previous(value);bindingLoop.quit();};auto replacement=WorkbookSession().snapshot();replacement["revision"]=boundRevision;swapped=WorkbookSession(replacement);QTimer bindingDeadline;bindingDeadline.setSingleShot(true);QObject::connect(&bindingDeadline,&QTimer::timeout,&bindingLoop,&QEventLoop::quit);bindingDeadline.start(10000);bindingLoop.exec();require(calculated&&swapped.snapshot()["sheets"][0]["cells"].empty(),"old macro cannot bind to replacement workbook with same revision");delete bindingDialog;
